cat << EOF > log_processor.sh
#!/bin/bash
LOG_FILE="app.log"
ARCHIVE_DIR="logs_archive"
check_log() {
  if [ ! -f "$LOG_FILE" ]; then
    echo "Error: $LOG_FILE not found!"
    exit 1
  fi
}
process_log() {
  local error_count=$(grep -c "ERROR" "$LOG_FILE")
  echo "Number of errors: $error_count"
}
archive_log() {
  mkdir -p "$ARCHIVE_DIR"
  mv "$LOG_FILE" "$ARCHIVE_DIR/app.log"
  echo "Log archived to: $ARCHIVE_DIR/app.log"
}
check_log
process_log
archive_log
EOF

